// Rebuild from a manifest (live-then-archive Phase 2, T2.3, non-circular proof): the notes
// are real Mac meeting files (copied from the committed Mac encoder fixture, the same bytes
// FrontmatterCoder writes), scanned from a temp folder into a manifest of key and SHA-256 hash,
// then turned into upserts by a node reader of that format. The test checks the index against
// the notes list (ground truth from the files), drops everything, rebuilds from the manifest,
// and checks the results and counts are the same. Nothing here is generated by the index.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import fs from 'node:fs';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

process.env.LLMIDE_JWT_SECRET = 'a'.repeat(48);
process.env.LLMIDE_VAULT_KEY = 'b'.repeat(48);
process.env.NODE_ENV = 'test';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const tmpDb = path.join(__dirname, '_note-index-manifest-test.db');
const tmpRoot = fs.mkdtempSync(path.join(process.env.TMPDIR || '/tmp', 'lta-notes-'));
process.env.LLMIDE_DB_PATH = tmpDb;
for (const f of [tmpDb, `${tmpDb}-wal`, `${tmpDb}-shm`]) fs.rmSync(f, { force: true });

const db = await import('../kb/db.mjs');
const users = await import('../server/users.mjs');
const ni = await import('../kb/note-index.mjs');
const conn = db.getDb();
const U = users.registerUser(conn, { email: `manifest-${Date.now()}@example.test`, password: 'CorrectHorseBattery', displayName: 'u' }).id;
const PROJECT = 'lta-manifest';

// The committed Mac fixture (written by FrontmatterCoder in LtaOldFormatFixtureTests).
const MAC_FIXTURE = path.join(__dirname, '../../mac/Tests/LlmIdeMacTests/Fixtures/lta/meeting-with-platform.md');
const MAC_NO_PLATFORM = path.join(__dirname, '../../mac/Tests/LlmIdeMacTests/Fixtures/lta/meeting-without-platform.md');

test.after(() => {
  db.closeDb();
  fs.rmSync(tmpRoot, { recursive: true, force: true });
  for (const f of [tmpDb, `${tmpDb}-wal`, `${tmpDb}-shm`]) fs.rmSync(f, { force: true });
});

/** Reads the Mac meeting format (FrontmatterCoder output): `---`, flat keys, a list, `---`, body. */
function readMacNote(text) {
  if (!text.startsWith('---\n')) return null;
  const end = text.indexOf('\n---\n', 4);
  if (end < 0) return null;
  const yaml = text.slice(4, end).split('\n');
  const fm = { participants: [] };
  let listKey = null;
  for (const line of yaml) {
    if (line.startsWith('- ') && listKey) { fm[listKey].push(line.slice(2).replace(/^'|'$/g, '')); continue; }
    const m = /^([a-z_]+):\s*(.*)$/.exec(line);
    if (!m) continue;
    listKey = m[2] === '' ? m[1] : null;
    if (listKey) fm[listKey] = [];
    else fm[m[1]] = m[2].replace(/^'|'$/g, '');
  }
  if (!fm.platform) return null;     // Library and the index both skip it (F13)
  return { fm, body: text.slice(end + 5) };
}

const sha256 = (buf) => crypto.createHash('sha256').update(buf).digest('hex');

/** The manifest a scan of `root` produces: key (forward slashes), hash of the bytes, and the note. */
function scanFolder(root) {
  const out = [];
  const walk = (dir) => {
    for (const name of fs.readdirSync(dir).sort()) {
      const full = path.join(dir, name);
      if (fs.statSync(full).isDirectory()) { walk(full); continue; }
      if (!name.endsWith('.md') || name.endsWith('.partial.md')) continue;
      const buf = fs.readFileSync(full);
      const key = path.relative(root, full).split(path.sep).join('/');
      out.push({ key, contentHash: sha256(buf), mtimeMs: Math.floor(fs.statSync(full).mtimeMs),
        note: readMacNote(buf.toString('utf8')), bytes: buf.length });
    }
  };
  walk(root);
  return out;
}

const toUpsert = (entry) => ({
  noteKey: entry.key, kind: 'meeting', title: entry.note.fm.title,
  date: entry.note.fm.started_at ?? entry.note.fm.startedAt, durationSec: Number(entry.note.fm.duration_seconds) || 0,
  participants: entry.note.fm.participants, body: entry.note.body, contentHash: entry.contentHash,
  mtimeMs: entry.mtimeMs, meta: { meetingId: entry.note.fm.id, platform: entry.note.fm.platform,
    language: entry.note.fm.language },
});

function writeNote(rel, text, mtime) {
  const full = path.join(tmpRoot, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, text);
  fs.utimesSync(full, mtime, mtime);
}

/** Notes in the Mac format: the committed fixture, with different ids, titles and bodies. */
function makeNotes() {
  const base = fs.readFileSync(MAC_FIXTURE, 'utf8');
  const variants = [
    ['2026/08/budget-review.md', base],
    ['2026/09/standup.md', base.replace('m-fixture-1', 'm-standup').replace('Budget review', 'Daily standup')
      .replace('we should raise the budget', 'we agreed to ship on Friday')],
    ['2026/09/review-ja.md', base.replace('m-fixture-1', 'm-ja').replace('Budget review', '予算レビュー')
      .replace('we should raise the budget', '来月の予算を確認しました。設計の見積もりは未定です。')],
    ['2026/10/rollback.md', base.replace('m-fixture-1', 'm-rollback').replace('Budget review', 'Rollback plan')
      .replace('we should raise the budget', 'the rollback plan uses a feature flag')],
    ['2026/10/planning.md', base.replace('m-fixture-1', 'm-planning').replace('Budget review', 'Quarterly planning')
      .replace('we should raise the budget', 'roadmap for the next quarter')],
  ];
  const mtime = new Date('2026-08-01T10:00:00Z');
  for (const [rel, text] of variants) writeNote(rel, text, mtime);
  // A note without platform: Mac and index both skip it.
  writeNote('2026/10/legacy.md', fs.readFileSync(MAC_NO_PLATFORM, 'utf8'), mtime);
}

function feed(entries) {
  return entries.filter((e) => e.note).map(toUpsert);
}

function indexAll(upserts) {
  for (let i = 0; i < upserts.length; i += 50) {
    ni.upsertNotes(U, upserts.slice(i, i + 50), { projectId: PROJECT });
  }
}

/** Ranked results for fixed queries, sorted, plus the note count: the state compared before and after. */
function snapshot(titles) {
  const out = {};
  for (const q of [...titles, 'roadmap', 'budget', 'rollback', 'standup', '予算']) {
    out[q] = ni.noteIndexHits(U, { q, limit: 10, projectId: PROJECT }).map((h) => `${h.meetingId}|${h.title}`).sort();
  }
  out.count = conn.prepare('SELECT COUNT(*) AS n FROM note_index WHERE user_id = ? AND project_id = ?').get(U, PROJECT).n;
  out.fts = conn.prepare("SELECT COUNT(*) AS n FROM search WHERE kind = 'note'").get().n;
  return out;
}

test('the index agrees with the notes list, drops to nothing, and rebuilds to the same state from the manifest', () => {
  makeNotes();
  const scanned = scanFolder(tmpRoot);
  const readable = scanned.filter((e) => e.note);
  // Ground truth: the notes list from the files (platform notes only).
  const notesList = readable.map((e) => e.note.fm.title).sort();
  const expectedIds = readable.map((e) => e.note.fm.id).sort();
  assert.equal(readable.length, 5, 'the platform-less legacy note is not a note the index can hold');
  assert.ok(scanned.some((e) => e.key === '2026/10/legacy.md' && !e.note));

  indexAll(feed(scanned));
  const before = snapshot(notesList);
  assert.equal(before.count, readable.length);
  assert.equal(before.fts, readable.length);
  // Every note in the list is findable by its title, and the index holds exactly the listed ids.
  const ids = conn.prepare('SELECT json_extract(meta, \'$.meetingId\') AS id FROM note_index WHERE user_id = ? AND project_id = ? ORDER BY id')
    .all(U, PROJECT).map((r) => r.id);
  assert.deepEqual(ids, expectedIds);
  for (const title of notesList) assert.ok(before[title].length >= 1, `"${title}" is findable`);

  // Drop everything the index holds, then rebuild from the manifest alone.
  conn.prepare('DELETE FROM note_index').run();
  conn.prepare("DELETE FROM search WHERE kind = 'note'").run();
  conn.prepare('DELETE FROM note_index_search').run();
  assert.equal(conn.prepare('SELECT COUNT(*) AS n FROM note_index').get().n, 0);
  indexAll(feed(scanFolder(tmpRoot)));
  assert.deepEqual(snapshot(notesList), before, 'the rebuilt index answers the same as before the drop');
});

test('a manifest reconcile against the rebuilt index prunes a note that left the folder, and nothing else', () => {
  const scanned = scanFolder(tmpRoot);
  const manifest = scanned.filter((e) => e.note).map((e) => ({ noteKey: e.key, contentHash: e.contentHash }));
  // A note removed from the folder is extra on the server; the rest must stay.
  fs.rmSync(path.join(tmpRoot, '2026/10/planning.md'));
  const after = scanFolder(tmpRoot).filter((e) => e.note).map((e) => ({ noteKey: e.key, contentHash: e.contentHash }));
  const r = ni.reconcileNotes(U, { projectId: PROJECT, manifest: after, prune: true });
  assert.deepEqual(r.extra, ['2026/10/planning.md']);
  assert.equal(r.pruned, 1);
  assert.equal(manifest.length - 1, after.length);
  assert.equal(ni.indexStatus(U, { projectId: PROJECT }).consistent, true);
});
